// FUNCTIONS //

/**
* Initializes private instance properties.
*
* @private
* @param {PlotBase} plotBase - plotBase instance
* @param {Object} defaults - default property values
* @returns {PlotBase} plotBase instance
*/
function initializePrivateProperties( plotBase, defaults ) { // eslint-disable-line id-length
	var definedValue;
	var i;
	for ( i = 0; i < PRIVATE_PROPS.length; i++ ) {
		definedValue = defaults[ PRIVATE_PROPS[ i ].substring( 1 ) ];
		defineProperty( plotBase, PRIVATE_PROPS[ i ], {
			'configurable': false,
			'enumerable': false,
			'writable': true,

			// eslint-disable-next-line no-undefined
			'value': ( definedValue === undefined ) ? null : definedValue
		});
	}
	return plotBase;
}


// MAIN //

/**
* Unicode table constructor.
*
* @constructor
* @param {Options} [options] - plot base options
* @param {boolean} [option.autoInitialization] - plot base options
* @param {boolean} [option.autoRender] - plot base options
* @param {string} [option.axisIntersectionGlyph='crossIntersection'] - plot base options
* @param {Array} [option.axisTicsLabels=[ [], [], [], [] ]] - plot base options
* @param {string} [option.backgroundColor='Bwhite'] - plot base options
* @param {string} [option.foregroundColor='Fblack'] - plot base options
* @param {string} [option.glyph='space'] - plot base options
* @param {string} [option.horizontalTicsGlyph='topTee'] - plot base options
* @param {string} [option.horizontalAxisGlyph='horizontal'] - plot base options
* @param {Array} [option.labelFormate=[ '%s', '%s', '%s', '%s']] - plot base options
* @param {NonNegativeInteger} [option.ploatAreaHeight=15] - plot base options
* @param {NonNegativeInteger} [option.plotAreaWidth=80] - plot base options
* @param {string} [option.ticsLabelsBckColor='Bwhite'] - plot base options
* @param {Array} [option.ticsSpacing=[ 1, 1, 1, 1]] - plot base options
* @param {string} [option.ticsLabelFrdColor='Fblack'] - plot base options
* @param {string} [option.verticalAxisGlyph='vertical'] - plot base options
* @param {NonNegativeInteger} [option.verticalTicsGlyph=80] - plot base options
* @param {boolean} [option.wAxis=false] - plot base options
* @param {NonNegativeInteger} [option.wAxisPos=0] - plot base options
* @param {Array} [option.wAxisTicsLabels=[]] - plot base options
* @param {NonNegativeInteger} [option.wTicsLabelSpace=1] - plot base options
* @param {NonNegativeInteger} [option.wTicsSpacing=1] - plot base options
* @param {boolean} [option.xAxis=false] - plot base options
* @param {NonNegativeInteger} [option.xAxisPos=0] - plot base options
* @param {Array} [option.xAxisTicsLabels=[]] - plot base options
* @param {NonNegativeInteger} [option.xTicsLabelSpace=1] - plot base options
* @param {NonNegativeInteger} [option.xTicsSpacing=1] - plot base options
* @param {boolean} [option.yAxis=false] - plot base options
* @param {NonNegativeInteger} [option.yAxisPos=0] - plot base options
* @param {Array} [option.yAxisTicsLabels=[]] - plot base options
* @param {NonNegativeInteger} [option.yTicsLabelSpace=1] - plot base options
* @param {NonNegativeInteger} [option.yTicsSpacing=1] - plot base options
* @param {boolean} [option.zAxis=false] - plot base options
* @param {NonNegativeInteger} [option.zAxisPos=0] - plot base options
* @param {Array} [option.zAxisTicsLabels=[]] - plot base options
* @param {NonNegativeInteger} [option.zTicsLabelSpace=1] - plot base options
* @param {NonNegativeInteger} [option.zTicsSpacing=1] - plot base options
* @throws {TypeError} data argument must be an object, an array of objects, an array of arrays, or a two-dimensional ndarray
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @returns {PlotBase} plotBase instance
*/
function PlotBase() {
	var options;
	var nargs;
	var opts;
	var keys;
	var self;
	var key;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof PlotBase ) ) {
		if ( nargs === 0 ) {
			return new PlotBase();
		}
		return new PlotBase( arguments[ 0 ] );
	}

	defineProperty( this, '_axisDataObjs', {
		'configurable': false,
		'enumerable': false,
		'writable': false,
		'value': [
			// X
			{
				'rawLabels': [],
				'normalizeLabels': [],
				'labelFormate': '%s',
				'axis': false,
				'ticsSpacing': 1,
				'position': 'default',
				'ticsLabelSpace': 1,
				'axisPos': 0
			},

			// Y
			{
				'rawLabels': [],
				'normalizeLabels': [],
				'labelFormate': '%s',
				'axis': false,
				'ticsSpacing': 1,
				'position': 'default',
				'ticsLabelSpace': 1,
				'axisPos': 0
			},

			// Z
			{
				'rawLabels': [],
				'normalizeLabels': [],
				'labelFormate': '%s',
				'axis': false,
				'ticsSpacing': 1,
				'position': 'default',
				'ticsLabelSpace': 1,
				'axisPos': 0
			},

			// W
			{
				'rawLabels': [],
				'normalizeLabels': [],
				'labelFormate': '%s',
				'axis': false,
				'ticsSpacing': 1,
				'position': 'default',
				'ticsLabelSpace': 1,
				'axisPos': 0
			}
		]
	});
	defineProperty( this, '_foregroundColorMatrix', {
		'configurable': false,
		'enumerable': false,
		'writable': false,
		'value': []
	});
	defineProperty( this, '_backgroundColorMatrix', {
		'configurable': false,
		'enumerable': false,
		'writable': false,
		'value': []
	});
	defineProperty( this, '_glyphMatrix', {
		'configurable': false,
		'enumerable': false,
		'writable': false,
		'value': []
	});

	// Initialize private instance properties:
	initializePrivateProperties( this, defaults() );
	this._quiet = false;

	// Resolve input arguments...
	if ( nargs === 0 ) {
		options = {};
	} else {
		options = arguments[ 0 ];
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
	}

	// Extract provided options while ignoring any extraneous/unsupported options properties:
	opts = pick( options, OPTIONS_PROPS );
	debug( 'Creating an instance with the following configuration: %s.', JSON.stringify( opts ) );

	// Validate provided options by assigning values to plotBase properties...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		key = keys[ i ];
		this[ key ] = opts[ key ];
	}

	// Add event listeners:
	this.on( 'change', onChange );
	this.on( 'render', onRender );
	this.on( 'initialize', onInitalization );
	self = this;
	return this;

	/**
	* Callback invoked upon receiving a `change` event.
	*
	* @private
	*/
	function onChange() {
		/* eslint-disable no-underscore-dangle */
		debug( 'Received a change event.' );
		if ( self._autoRender ) {
			self.render();
		}
	}

	/**
	* Callback invoked upon receiving a `render` event.
	*
	* @private
	* @param {string} str - render string
	*/
	function onRender() {
		debug( 'Received a render event.' );
	}

	/**
	* Callback invoked upon receiving a `initialize` event.
	*
	* @private
	* @param {string} table - rendered table
	*/
	function onInitalization() {
		debug( 'Received a initialize event.' );
		if ( self.autoInitialization ) {
			self.initialize();
		}
	}
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( PlotBase, EventEmitter );

/**
* Initialization mode.
*
* ## Notes
*
* -   If `true`, an instance automatically re-initialize a plot base on each `initialize` event.
*
* @name autoInitialization
* @memberof UnicodeTable.prototype
* @type {boolean}
* @throws {TypeError} must be a boolean
* @default false
*
* @example
* var plotBase = new PlotBase();
*
* plotBase.autoInitialization = true;
*
* var v = plotBase.autoInitialization;
* // returns true
*/
setReadWriteAccessor( PlotBase.prototype, 'autoInitialization', getAutoInitialization, setAutoInitialization );

/**
* Rendering mode.
*
* ## Notes
*
* -   If `true`, an instance automatically re-renders a base plot on each `change` event.
*
* @name autoRender
* @memberof UnicodeTable.prototype
* @type {boolean}
* @throws {TypeError} must be a boolean
* @default false
*
* @example
* var plotBase = new PlotBase();
*
* plotBase.autoRender = true;
*
* var v = plotBase.autoRender;
* // returns true
*/
setReadWriteAccessor( PlotBase.prototype, 'autoRender', getAutoRender, setAutoRender );

